import React,{act,StrictMode,useLayoutEffect} from 'react';
import {createRoot,type Root} from 'react-dom/client';
import {App} from 'm925-catalog-integration-app';
import type {NamingSession} from '../../src/shared/types';
import type {CulturalWorkflowAPI,CulturalComparisonRead} from '../../src/shared/cultural-workflow-api';
import type {CulturalComparisonCatalogAPI,CulturalComparisonCatalogMetadata,CulturalComparisonCatalogPage,CulturalComparisonCatalogRequest} from '../../src/shared/cultural-comparison-catalog';
import type {CulturalComparisonSnapshot} from '../../src/shared/qimen-cultural-comparison';
import type {CulturalRevision} from '../../src/shared/cultural-storage-v3';
import {canonicalPlainJson} from '../../src/shared/plain-json';

type Method=keyof CulturalWorkflowAPI|keyof CulturalComparisonCatalogAPI|'readSessionDetail';
type Call={method:Method;args:unknown[]};
type Seeds={sessions:NamingSession[];snapshots:Record<string,CulturalComparisonSnapshot>};
type Deferred<T>={promise:Promise<T>;resolve:(value:T)=>void;reject:(error:Error)=>void};
type Case={id:string;status:'passed'|'failed';assertions:number;error?:string;html:string;calls:Call[]};
declare global {interface Window {__M925_CATALOG_APP_SEEDS__:Seeds;__M925_CATALOG_APP_RESULT__?:{scope:string;runtime:{userAgent:string;strictMode:boolean};cases:Case[];errors:string[];unhandled:string[];fatal?:string};}}
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value));
const deferred=<T,>():Deferred<T>=>{let resolve!:(value:T)=>void,reject!:(error:Error)=>void;const promise=new Promise<T>((yes,no)=>{resolve=yes;reject=no;});return {promise,resolve,reject};};
Object.assign(globalThis,{IS_REACT_ACT_ENVIRONMENT:true});
const host=document.getElementById('root')!;
let root:Root|undefined,assertions=0,currentCalls:Call[]=[];
const cases:Case[]=[],errors:string[]=[],unhandled:string[]=[];
window.addEventListener('error',event=>errors.push(event.message));
window.addEventListener('unhandledrejection',event=>unhandled.push(String(event.reason)));
const check=(condition:unknown,message:string)=>{assertions++;if(!condition)throw Error(message);};
const equal=(actual:unknown,expected:unknown,message:string)=>check(canonicalPlainJson(actual)===canonicalPlainJson(expected),message+'\nactual='+JSON.stringify(actual)+'\nexpected='+JSON.stringify(expected));
const tick=()=>new Promise<void>(resolve=>setTimeout(resolve,0));
async function settle(){await act(async()=>{await tick();await tick();});}
async function wait(ready:()=>boolean,message:string){const started=performance.now();while(!ready()){if(performance.now()-started>4000)throw Error(message+'\nDOM='+host.innerText.slice(-4500));await settle();}await settle();}
const query=<T extends Element=HTMLElement>(selector:string)=>host.querySelector<T>(selector);
const nodes=<T extends Element=HTMLElement>(selector:string)=>[...host.querySelectorAll<T>(selector)];
const catalog=()=>query('[data-cultural-saved-catalog]');
const action=(name:string)=>query<HTMLButtonElement>('[data-cultural-saved-catalog] [data-catalog-action="'+name+'"]');
const detail=()=>query('[data-cultural-saved-detail]');
const record=(id:string)=>query<HTMLButtonElement>('[data-cultural-record="'+id+'"]');
const count=(name:Method)=>currentCalls.filter(call=>call.method===name).length;
const calls=(name:Method)=>currentCalls.filter(call=>call.method===name);
const originalId='qc_'+'f'.repeat(64),currentId='qc_'+'e'.repeat(64),foreignId='qc_'+'d'.repeat(64);
async function nativeClick(element:HTMLElement|null,message='Missing native control'){check(element,message);check(!element!.matches(':disabled'),'Native control is disabled: '+message);await act(async()=>{element!.click();});await settle();}
async function click(name:string){await nativeClick(action(name),'catalog action '+name);}
async function clickText(text:string,selector='button'){const value=[...document.querySelectorAll<HTMLElement>(selector)].find(node=>(node.textContent??'').trim()===text);await nativeClick(value??null,'button '+text);}
function capture(element:HTMLElement|null){check(element,'Missing handler capture target');const key=Object.keys(element!).find(value=>value.startsWith('__reactProps$'));check(key,'Real ReactDOM event props absent');const props=(element as unknown as Record<string,unknown>)[key!] as {onClick?:()=>void};check(typeof props.onClick==='function','onClick absent');return props.onClick!;}
async function invoke(callback:()=>void){await act(async()=>callback());await settle();}
async function input(selector:string,value:string){const node=query<HTMLInputElement>(selector);check(node,'Missing input '+selector);await act(async()=>{Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value')!.set!.call(node,value);node!.dispatchEvent(new Event('input',{bubbles:true}));node!.dispatchEvent(new Event('change',{bubbles:true}));});await settle();}
async function unmount(){if(root)await act(async()=>root!.unmount());root=undefined;await settle();}

function transport({missing=false,readOnly=false,mode='available'}:{missing?:boolean;readOnly?:boolean;mode?:'available'|'unsupported'|'cursor-expired-next'|'foreign-metadata'|'injected-metadata'}={}){
 const sessions=clone(window.__M925_CATALOG_APP_SEEDS__.sessions),snapshots=clone(window.__M925_CATALOG_APP_SEEDS__.snapshots),trace:Call[]=[];currentCalls=trace;
 const records=new Map([[originalId,sessions[1]],[currentId,sessions[0]],[foreignId,sessions[2]]]);
 const paused=new Map<Method,Deferred<unknown>[]>();
 const state={mode,detailMode:'normal' as 'normal'|'foreign-owner'|'foreign-id',sourceReads:0};
 const metadata=(id:string):CulturalComparisonCatalogMetadata=>{const session=records.get(id)!;return {comparisonId:id,ownerProfileId:session.profileId,sourceSessionId:session.id,currentRevision:2,createdAt:'2026-10-26T00:00:00Z',factsAuthenticated:false,sourceAuthority:'not-authenticated-facts'};};
 const page=(owner:string,request:CulturalComparisonCatalogRequest={}):CulturalComparisonCatalogPage=>{
  const boundary={schema:'cultural-comparison-catalog/1' as const,ownerProfileId:owner,storageVersion:state.mode==='unsupported'?'customer-compact/2' as const:'customer-compact/3' as const,limit:request.limit??10,order:'comparison-id-desc' as const,factsAuthenticated:false as const,sourceAuthority:'not-authenticated-facts' as const};
  if(state.mode==='unsupported')return {...boundary,status:'unsupported',reason:'cultural-tables-unavailable',items:[]};
  if(state.mode==='cursor-expired-next'&&request.cursor)return {...boundary,status:'cursor-expired',reason:'database-changed',items:[]};
  const id=owner===sessions[2].profileId?foreignId:request.cursor?currentId:originalId;
  if(state.mode==='foreign-metadata')return {...boundary,status:'available',items:[{...metadata(id),ownerProfileId:sessions[2].profileId}]};
  if(state.mode==='injected-metadata')return {...boundary,status:'available',items:[{...metadata(id),reviewToken:'forbidden-token-in-metadata',note:'FORBIDDEN-METADATA-NOTE',sourceJSON:'FORBIDDEN-SOURCE-JSON',factsAuthenticated:true} as unknown as CulturalComparisonCatalogMetadata]};
  return {...boundary,status:'available',items:[metadata(id)],...(id===originalId?{nextCursor:'bTIzY3Vyc29yMQ'}:{})};
 };
 const revision=(id:string,number:number):CulturalRevision=>({comparisonId:id,revision:number,profileId:records.get(id)!.profileId,parentRevision:number===1?null:number-1,operation:number===1?'create':'revise',restoredFromRevision:null,capsule:{sha:'a'.repeat(64),rawBytes:1,codec:'deflate-raw/1',role:'evidence'},result:{sha:'b'.repeat(64),rawBytes:1,codec:'deflate-raw/1',role:'revision-result'},createdAt:'2026-10-26T00:00:00Z'});
 const history=(id:string)=>[revision(id,2),revision(id,1)];
 const read=(id:string,number=2):CulturalComparisonRead=>{
  const session=records.get(id)!;
  const value:CulturalComparisonRead={head:{id,profileId:session.profileId,sourceSessionId:session.id,currentRevision:2,reviewToken:'44444444-4444-4444-8444-444444444444',createdAt:'2026-10-26T00:00:00Z'},revision:revision(id,number),result:{schema:'qimen-cultural-revision/1.0.0',comparisonId:id,revision:number,profileId:session.profileId,sourceSessionId:session.id,capsuleDigest:'c'.repeat(64),snapshot:clone(snapshots[session.id]),note:'原保存独立备注 · '+id+' · 修订 '+number,noteAuthority:'human-note-only',createdAt:'2026-10-26T00:00:00Z',operation:number===1?'create':'revise',restoredFromRevision:null}};
  if(state.detailMode==='foreign-owner')value.result.profileId=sessions[2].profileId;
  if(state.detailMode==='foreign-id')value.head.id=foreignId;
  return value;
 };
 const returned=<T,>(method:Method,args:unknown[],make:()=>T):Promise<T>=>{trace.push({method,args:clone(args)});const pending=paused.get(method)?.shift();return pending?pending.promise as Promise<T>:Promise.resolve(clone(make()));};
 const writes=['prepareCulturalWrite','commitCulturalWrite','restoreCulturalRevision','migrateCulturalStorage'] as const;
 const cultural=Object.fromEntries(writes.map(method=>[method,(...args:unknown[])=>returned(method,args,()=>{throw Error('M925 read-only fixture forbids writes');})]));
 const studio={
  ...cultural,
  ...(!missing?{listCulturalComparisons:(owner:string,request:CulturalComparisonCatalogRequest={})=>returned('listCulturalComparisons',[owner,request],()=>page(owner,request))}:{}),
  readCulturalComparison:(id:string,number?:number)=>returned('readCulturalComparison',number===undefined?[id]:[id,number],()=>read(id,number)),
  listCulturalRevisions:(id:string)=>returned('listCulturalRevisions',[id],()=>history(id)),
  readSessionDetail:(id:string)=>returned('readSessionDetail',[id],()=>{state.sourceReads++;return sessions.find(session=>session.id===id)??null;}),
  getCulturalStorageCapabilities:()=>returned('getCulturalStorageCapabilities',[],()=>({version:'customer-compact/3',hasRootLeafRefs:true,hasRevisionProfileId:true,hasCulturalTables:true})),
  prepareCulturalBirthAnchor:(...args:unknown[])=>returned('prepareCulturalBirthAnchor',args,()=>{throw Error('Saved catalog does not prepare a current chart');}),
  getCulturalCharacterOptions:(...args:unknown[])=>returned('getCulturalCharacterOptions',args,()=>{throw Error('Saved catalog does not query current candidates');}),
  previewCulturalComparison:(...args:unknown[])=>returned('previewCulturalComparison',args,()=>{throw Error('Saved catalog does not create a preview');}),
  previewCulturalStorageMigration:()=>returned('previewCulturalStorageMigration',[],()=>{throw Error('Saved catalog does not migrate');}),
  bootstrap:async()=>({profiles:[clone(sessions[0].profile),clone(sessions[2].profile)],sessions:clone(sessions),settings:{studioName:'M925 DOM工作室',contact:'',logoDataUrl:'',apiBaseUrl:'',model:'',timeoutMs:45000,hasApiKey:false,useAi:false},sources:[],stats:{characters:100,citations:20,knowledge:20,dataVersion:'m923-fixture'},desktop:true,storageState:{version:'customer-compact/3',migrationRequired:readOnly,bytes:1,maxPhysicalBytes:1000000,warning:false}}),
  generate:async()=>({session:clone(sessions[0]),messages:[]}),
  searchKnowledge:async()=>[],searchCharacters:async()=>[],
 };
 return {studio,sessions,snapshots,trace,state,page,read,history,pause:(method:Method)=>{const pending=deferred<unknown>();paused.set(method,[...(paused.get(method)??[]),pending]);return pending;}};
}

async function mount(options:Parameters<typeof transport>[0]={}){
 await unmount();const stub=transport(options);window.studio=stub.studio as unknown as typeof window.studio;
 window.localStorage.setItem('studio.onboarding.v1',JSON.stringify({version:1,dismissed:true}));window.confirm=()=>true;
 host.replaceChildren();root=createRoot(host);let mounts=0,cleanups=0;
 function Probe(){useLayoutEffect(()=>{mounts++;return()=>{cleanups++;};},[]);return null;}
 await act(async()=>root!.render(<StrictMode><Probe/><App/></StrictMode>));await wait(()=>!!catalog(),'Actual App catalog entry absent');
 check(mounts===2&&cleanups===1,'Real StrictMode did not replay effects');return stub;
}
async function openSaved(stub:ReturnType<typeof transport>,index=0){const session=stub.sessions[index];await nativeClick(query<HTMLButtonElement>('button.catalog-item[title*="'+session.id+'"]'),'Actual saved session entry');await wait(()=>query('.current-session-label')?.textContent?.includes(session.profile.customerName)??false,'Saved App session did not load');return session;}
async function openList(stub:ReturnType<typeof transport>,index=0){const session=await openSaved(stub,index);await click('open');await wait(()=>!!record(index===2?foreignId:originalId),'Metadata catalog did not load');return session;}
async function openRecord(id=originalId){await nativeClick(record(id),'saved cultural metadata row');await wait(()=>!!detail(),'Original cultural record/history did not load');}
async function scenario(id:string,work:()=>Promise<void>){const beforeErrors=errors.length,beforeUnhandled=unhandled.length;assertions=0;try{await work();check(errors.length===beforeErrors,'Window errors '+errors.slice(beforeErrors).join('\n'));check(unhandled.length===beforeUnhandled,'Unhandled rejection '+unhandled.slice(beforeUnhandled).join('\n'));cases.push({id,status:'passed',assertions,html:host.innerHTML,calls:clone(currentCalls)});}catch(error){cases.push({id,status:'failed',assertions,error:error instanceof Error?error.stack:String(error),html:host.innerHTML,calls:clone(currentCalls)});}finally{await unmount();}}

async function run(){
 await scenario('default-and-remount-have-zero-catalog-calls',async()=>{let stub=await mount();await openSaved(stub);equal(stub.trace,[],'Saved owner automatically loaded cultural directory');await unmount();stub=await mount();await openSaved(stub);equal(stub.trace,[],'Remount used a hidden comparison ID or read automatically');await click('open');await wait(()=>!!record(originalId),'Explicit open did not discover stored comparison');equal(calls('listCulturalComparisons')[0].args,[stub.sessions[0].profileId,{limit:10}],'Directory did not use exact owner and bounded limit');equal(count('readCulturalComparison'),0,'Directory metadata automatically loaded facts');});
 await scenario('metadata-never-grants-source-authority',async()=>{const stub=await mount();await openList(stub);check(/目录|索引|元数据/.test(catalog()!.textContent??''),'Metadata boundary not described');check(/未.*核|不.*核|不代表.*来源|not-authenticated/.test(catalog()!.textContent??''),'Metadata source authority caveat absent');check(!(catalog()!.textContent??'').includes('原保存独立备注'),'Metadata leaked notes');check(!detail(),'Metadata was displayed as a complete saved result');equal(count('readCulturalComparison'),0,'Metadata auto-read detail');equal(count('listCulturalRevisions'),0,'Metadata auto-read history');});
 await scenario('record-waits-for-real-read-and-history-before-showing-snapshot',async()=>{const stub=await mount();await openList(stub);const pending=stub.pause('listCulturalRevisions');await nativeClick(record(originalId));await wait(()=>count('listCulturalRevisions')===1,'History API was not called');check(!detail(),'Snapshot appeared before history returned');equal(calls('readCulturalComparison')[0].args,[originalId],'Detail did not use exact selected comparison ID');await act(async()=>pending.resolve(stub.history(originalId)));await wait(()=>!!detail(),'Both completed reads did not show original result');check(detail()!.textContent!.includes(stub.sessions[1].id),'Original source session not displayed');check(detail()!.textContent!.includes('原保存独立备注'),'Original independent note missing');check(/保存记录|原保存|已保存/.test(detail()!.textContent??''),'Saved-record presentation boundary absent');equal(nodes('[data-cultural-saved-detail] [data-cultural-candidate]').length,2,'Original saved snapshot candidates missing');});
 await scenario('cross-session-record-opens-actual-source-session-only-on-explicit-action',async()=>{const stub=await mount();await openList(stub);await openRecord();check(detail()!.textContent!.includes(stub.sessions[1].id),'Cross-session saved record forced current anchor');equal(count('readSessionDetail'),0,'Readonly inspection implicitly opened source session');await click('open-source-session');await wait(()=>count('readSessionDetail')===1,'Explicit source action did not use actual API');equal(calls('readSessionDetail')[0].args,[stub.sessions[1].id],'Wrong original saved session fetched');await wait(()=>query('.current-session-label')?.textContent?.includes(stub.sessions[1].profile.customerName)??false,'Actual source session was not applied');});
 await scenario('open-original-session-preserves-existing-dirty-confirmation',async()=>{const stub=await mount();await openList(stub);await openRecord();await input('#birth-date','2026-10-18');check(!!detail(),'Editing current input destroyed independent original saved record');await click('open-source-session');await wait(()=>document.body.textContent!.includes('有修改尚未保存'),'Original dirty confirmation not shown');equal(count('readSessionDetail'),0,'Source fetch preceded dirty confirmation');await clickText('继续编辑');equal(count('readSessionDetail'),0,'Cancel dirty confirmation fetched source');equal(query<HTMLInputElement>('#birth-date')!.value,'2026-10-18','Cancel lost current dirty input');await click('open-source-session');await clickText('放弃修改并继续');await wait(()=>count('readSessionDetail')===1,'Confirmed original session did not fetch');equal(calls('readSessionDetail')[0].args,[stub.sessions[1].id],'Dirty-confirmed fetch used current session');await wait(()=>query<HTMLInputElement>('#birth-date')?.value===stub.sessions[1].profile.birthDate,'Source session was not applied after confirmation');});
 await scenario('pending-source-session-read-preserves-new-same-owner-date',async()=>{const stub=await mount();await openList(stub);await openRecord();const pending=stub.pause('readSessionDetail');await click('open-source-session');await wait(()=>count('readSessionDetail')===1,'Actual original-session read did not start');equal(calls('readSessionDetail')[0].args,[stub.sessions[1].id],'Pending source read used wrong saved session');check(query('main.main-area')?.getAttribute('aria-busy')==='true','Source read did not hold root busy');await input('#birth-date','2026-10-19');equal(query<HTMLInputElement>('#birth-date')!.value,'2026-10-19','Same-owner edit was not accepted while source read pending');await act(async()=>pending.resolve(clone(stub.sessions[1])));await wait(()=>query('main.main-area')?.getAttribute('aria-busy')==='false','Settled source read did not release root busy');equal(query<HTMLInputElement>('#birth-date')!.value,'2026-10-19','Late source session replaced newer same-owner date');check(host.textContent!.includes('当前新输入已保留'),'New-input preservation notice absent');check(!query('.current-session-label')?.textContent?.includes(stub.sessions[1].profile.customerName),'Late source response applied the old original session');equal(count('readSessionDetail'),1,'Stale source response retried automatically');});
 await scenario('owner-change-discards-late-directory-and-details',async()=>{const stub=await mount();await openSaved(stub);const pending=stub.pause('listCulturalComparisons');await click('open');await wait(()=>count('listCulturalComparisons')===1,'Owner A list did not start');await nativeClick(query('button.new-profile'));await openSaved(stub,2);await click('open');await wait(()=>!!record(foreignId),'Owner B list missing');await act(async()=>pending.resolve(stub.page(stub.sessions[0].profileId,{limit:10})));check(!record(originalId),'Owner A late metadata appeared for B');check(!!record(foreignId),'B metadata was replaced');check(!detail(),'Owner change retained old detail');});
 await scenario('cursor-navigation-retires-pending-old-record',async()=>{const stub=await mount();await openList(stub);const pending=stub.pause('readCulturalComparison');await nativeClick(record(originalId));await wait(()=>count('readCulturalComparison')===1,'Detail request absent');await click('close');await click('open');await wait(()=>!!record(originalId),'Explicit reopen did not restore first metadata page');await click('next');await wait(()=>!!record(currentId),'Next cursor page did not replace metadata');equal(calls('listCulturalComparisons').at(-1)!.args,[stub.sessions[0].profileId,{limit:10,cursor:'bTIzY3Vyc29yMQ'}],'Opaque cursor changed');await act(async()=>pending.resolve(stub.read(originalId)));check(!detail(),'Old page late detail entered new cursor page');check(!record(originalId),'Old cursor row persisted');});
 await scenario('expired-cursor-clears-old-data-and-restarts-only-explicitly',async()=>{const stub=await mount({mode:'cursor-expired-next'});await openList(stub);await openRecord();await click('next');await wait(()=>/失效|过期|重新从头|cursor-expired/.test(catalog()!.textContent??''),'Expired cursor not explained');check(!detail()&&!record(originalId),'Expired cursor retained old facts or metadata');equal(count('listCulturalComparisons'),2,'Expired cursor automatically restarted');await click('restart');await wait(()=>!!record(originalId),'Explicit restart did not reload first page');equal(calls('listCulturalComparisons').at(-1)!.args,[stub.sessions[0].profileId,{limit:10}],'Restart reused stale cursor');});
 await scenario('unsupported-storage-does-not-migrate-or-fabricate-empty-success',async()=>{const stub=await mount({mode:'unsupported'});await openSaved(stub);await click('open');await wait(()=>/不支持|不可用|未.*文化.*表|unsupported/.test(catalog()!.textContent??''),'Unsupported catalog state not explained');equal(count('listCulturalComparisons'),1,'Unsupported state retried automatically');equal(count('readCulturalComparison'),0,'Unsupported metadata read facts');equal(count('migrateCulturalStorage'),0,'Unsupported directory auto-migrated');check(!detail()&&!record(originalId),'Unsupported state fabricated success');});
 await scenario('foreign-metadata-and-injected-authority-are-rejected',async()=>{for(const mode of ['foreign-metadata','injected-metadata'] as const){const stub=await mount({mode});await openSaved(stub);await click('open');await wait(()=>/归属|不一致|无效|错误|失败|不符|异常/.test(catalog()!.textContent??''),'Invalid metadata was not rejected');check(!record(originalId)&&!detail(),'Invalid metadata became a selectable factual record');check(!catalog()!.textContent!.includes('FORBIDDEN-METADATA-NOTE'),'Injected metadata note leaked');check(!catalog()!.textContent!.includes('FORBIDDEN-SOURCE-JSON'),'Injected source JSON leaked');equal(count('readCulturalComparison'),0,'Invalid metadata triggered detail');}});
 await scenario('foreign-detail-id-or-owner-never-shows-saved-snapshot',async()=>{for(const mode of ['foreign-owner','foreign-id'] as const){const stub=await mount();await openList(stub);stub.state.detailMode=mode;await nativeClick(record(originalId));await wait(()=>/归属|不一致|无效|错误|失败|不符|异常/.test(catalog()!.textContent??''),'Foreign detail not rejected');check(!detail(),'Foreign detail displayed original snapshot');equal(nodes('[data-cultural-saved-catalog] [data-cultural-candidate]').length,0,'Foreign detail leaked candidate facts');}});
 await scenario('historical-selection-reads-exact-original-revision',async()=>{const stub=await mount();await openList(stub);await openRecord();await nativeClick(query('[data-cultural-revision="1"]'),'Original historical revision');await wait(()=>calls('readCulturalComparison').some(call=>call.args[0]===originalId&&call.args[1]===1),'Historical revision was not read from actual API');await wait(()=>!!detail()&&detail()!.textContent!.includes('修订 1'),'Historical result did not show original revision');equal(count('restoreCulturalRevision'),0,'Viewing history restored or wrote a revision');});
 await scenario('read-only-storage-can-browse-original-record-with-zero-writes',async()=>{const stub=await mount({readOnly:true});await openList(stub);await openRecord();equal(count('prepareCulturalWrite'),0,'Readonly viewer prepared a write');equal(count('commitCulturalWrite'),0,'Readonly viewer committed');equal(count('restoreCulturalRevision'),0,'Readonly viewer restored');equal(count('migrateCulturalStorage'),0,'Readonly viewer migrated');check(!!detail(),'Readonly state blocked saved inspection');});
 await scenario('missing-catalog-api-stays-explicit-and-produces-no-fake-record',async()=>{const stub=await mount({missing:true});await openSaved(stub);const open=action('open');if(open&&!open.matches(':disabled'))await nativeClick(open);await wait(()=>/未接入|不可用|尚未.*连接|未.*连接|不支持/.test(catalog()!.textContent??''),'Missing catalog API not visible');equal(count('listCulturalComparisons'),0,'Missing API made a synthetic request');check(!record(originalId)&&!detail(),'Missing API fabricated saved facts');});
 window.__M925_CATALOG_APP_RESULT__={scope:'Actual App source + native Electron Chromium ReactDOM StrictMode; explicit fixture bootstrap, catalog metadata and read APIs. No live Service/HTTP/Store verification, no hidden comparison-id persistence.',runtime:{userAgent:navigator.userAgent,strictMode:true},cases,errors,unhandled};
}
run().catch(error=>{window.__M925_CATALOG_APP_RESULT__={scope:'M925 actual App DOM with fixture transport only.',runtime:{userAgent:navigator.userAgent,strictMode:true},cases,errors,unhandled,fatal:error instanceof Error?error.stack:String(error)};});
